    result = []
    for char in message:
        if char.isalpha():
            if char in vowels:
                base = ord('a') if char.islower() else ord('A')
                char = chr((ord(char) - base + 2) % 26 + base)
            result.append(char.swapcase())
        else:
            result.append(char)
    return ''.join(result)

